create table if not exists public.api_usage (id bigint generated by default as identity primary key,service text not null,endpoint text not null,units integer not null default 0 check(units>=0),metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now()); alter table public.api_usage enable row level security; create index if not exists api_usage_created_at_idx on public.api_usage(created_at desc); create index if not exists api_usage_service_created_at_idx on public.api_usage(service,created_at desc);